using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Revert to old name for compatibility
            // with existing 500K documents and direct SQL queries.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityType|Key"
            // to just the key value. Revert to old format for existing documents.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 removed support for client-side evaluation of indexes.
            // Cosmos DB indexes are managed via indexing policy, not EF.
            // Removed: entity.HasIndex(p => p.Sku);
        });
    }
}

